import 'package:flutter/material.dart';
import 'dashboard_service.dart';

class DriverDashboard extends StatefulWidget{const DriverDashboard({super.key});@override State<DriverDashboard>createState()=>_DriverDashboardState();}
class _DriverDashboardState extends State<DriverDashboard>{final s=DashboardService();bool loading=true;String? error;Map<String,dynamic>d={};@override void initState(){super.initState();load();}Future<void>load()async{try{final x=await s.driverOverview();if(mounted)setState((){d=x;loading=false;});}catch(e){if(mounted)setState((){error=e.toString();loading=false;});}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!),FilledButton(onPressed:load,child:const Text('Retry'))]));final x=Map<String,dynamic>.from((d['driver']as Map?)??{});return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('Driver Dashboard',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.directions_bus)),title:Text(x['registrationNo']?.toString()??'Vehicle not assigned'),subtitle:Text('${x['vehicleType']??'School transport'} • ${x['routeName']??'Route not assigned'}'))),Row(children:[Expanded(child:_stat(c,'Students',x['studentCount']??0,Icons.groups)),Expanded(child:_stat(c,'Trip','${x['tripStatus']??'planned'}',Icons.route))]),const SizedBox(height:12),Card(child:ListTile(leading:const Icon(Icons.location_on),title:const Text('Today’s Route'),subtitle:Text(x['routeName']?.toString()??'No route assigned'))),Card(child:ListTile(leading:const Icon(Icons.security),title:const Text('Safety'),subtitle:const Text('Student boarding and drop events are recorded securely.')))]));}Widget _stat(BuildContext c,String t,Object v,IconData i)=>TweenAnimationBuilder<double>(tween:Tween(begin:0,end:1),duration:const Duration(milliseconds:500),builder:(x,n,ch)=>Transform.scale(scale:.94+.06*n,child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i),const SizedBox(height:6),Text('$v',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text(t)])))));}
